// Playwright E2E skeleton
test('checkout with promo code', async ({ page }) => {
  await seedTestData({ locale: 'en-US', promo: 'SAVE20' });
  await page.goto('/cart');

  // Apply promo code
  await page.getByLabel('Promo Code').fill('SAVE20');
  await page.getByRole('button', { name: 'Apply' }).click();

  // Verify discount applied
  await expect(page.locator('.discount')).toHaveText('-$20.00');
  await expect(page.locator('.total')).toHaveText('$80.00');

  // Mobile viewport
  await page.setViewportSize({ width: 375, height: 812 });
  await expect(page.locator('.total')).toHaveText('$80.00');

  // Switch locale
  await page.getByLabel('Language').selectOption('de-DE');
  await expect(page.locator('.discount')).toHaveText('-€18,00');

  // Checkout with stock race condition
  await page.goto('/checkout');
  await mockInventoryDecrement();
  await page.getByRole('button', { name: 'Pay' }).click();
  await expect(page.locator('.error')).toContainText('insufficient stock');
});
```

